    class: enums_1.DartIdentifierKind.Class,
    mixinApplication: enums_1.DartIdentifierKind.Class,
    enum: enums_1.DartIdentifierKind.Enum,
    mixin: enums_1.DartIdentifierKind.Mixin,
    extension: enums_1.DartIdentifierKind.Extension,
    extensionType: enums_1.DartIdentifierKind.ExtensionType,
