      const kind =
        m.memberKind === enums_1.DartMemberKind.Getter
          ? enums_1.DartIdentifierKind.Getter
          : m.memberKind === enums_1.DartMemberKind.Setter
            ? enums_1.DartIdentifierKind.Setter
            : enums_1.DartIdentifierKind.Method;
